import { chromium } from "playwright";
const browser=await chromium.launch({headless:true,args:["--enable-webgl","--ignore-gpu-blocklist","--use-gl=angle","--use-angle=swiftshader","--enable-unsafe-swiftshader"]});
const failures=[],errors=[];
try{
  const context=await browser.newContext({viewport:{width:390,height:844},deviceScaleFactor:2,isMobile:true,hasTouch:true});
  const page=await context.newPage();
  page.on("pageerror",e=>errors.push(e.message));
  page.on("console",m=>{if(m.type()==="error")errors.push(m.text());});
  const response=await page.goto("http://127.0.0.1:4173/game.html",{waitUntil:"domcontentloaded",timeout:30000});
  if(!response?.ok())failures.push("game page did not return HTTP 200");
  await page.waitForSelector("#world canvas",{timeout:45000});
  const canvas=page.locator("#world canvas");
  if(!(await canvas.isVisible()))failures.push("game canvas is not visible");
  const webgl=await canvas.evaluate(el=>Boolean(el.getContext("webgl2")));
  if(!webgl)failures.push("WebGL2 context unavailable");
  await page.keyboard.down("ArrowUp");
  await page.waitForTimeout(1200);
  await page.keyboard.up("ArrowUp");
  const moved=await page.evaluate(()=>({z:window.__gameDiagnostics?.vehicleZ,speed:window.__gameDiagnostics?.speed,battery:window.__gameDiagnostics?.battery}));
  if(!(moved.speed>0&&moved.z<48))failures.push("keyboard driving did not move the CNG: "+JSON.stringify(moved));
  if(!(moved.battery<100))failures.push("battery simulation did not update");
  await page.locator("#pause").click();
  if(!(await page.locator("#pause-panel").isVisible()))failures.push("pause overlay did not open");
  await page.locator("#resume").click();
  if(!(await page.locator("#pause-panel").isHidden()))failures.push("resume did not close pause overlay");
  await context.close();
  const menuContext=await browser.newContext({viewport:{width:1280,height:800}});
  const menu=await menuContext.newPage();
  await menu.goto("http://127.0.0.1:4173/index.html",{waitUntil:"domcontentloaded"});
  await menu.waitForSelector("#new-game:not(:disabled)",{timeout:15000});
  await menu.waitForSelector("#continue-game:not(:disabled)",{timeout:15000});
  await menu.locator("#continue-game").click();
  await menu.waitForURL("**/game.html?continue=1",{timeout:15000});
  await menu.goto("http://127.0.0.1:4173/index.html",{waitUntil:"domcontentloaded"});
  await menu.locator("#new-game").click();
  await menu.waitForURL("**/game.html?new=1",{timeout:15000});
  console.log("Save/Continue, New Game navigation and mobile driving passed.");
  await menuContext.close();
}finally{await browser.close();}
if(errors.length)failures.push(...errors);
if(failures.length){for(const f of failures)console.error("FAIL: "+f);process.exit(1);}
console.log("Playable game browser acceptance passed.");